      lines: [{ qty: 1, unitPrice: 10000, discountPercent: 10, vatRate: 0 }],
    },
  ];

  const csv = exportCsv(invoices);
  // 10000 * 0.10 = 1000 = 10.00
  const lines = csv.split('\n');
  const dataLine = lines[1];
  const fields = dataLine.split(',');
  // discount is at index 6
  assert.equal(fields[6], '10.00');
});

